import { useState } from "react";
import commonStyles from "../InputStyles.module.scss";
import { IconEye, IconEyeOff } from "@tabler/icons-react";

interface TextInputProps {
  label?: string;
  customClassName?: string;
  errorMessage?: string;
  placeholder?: string;
  type?: "text" | "password" | "email" | "number" | "tel";
  value?: string | number;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
}
const TextInput: React.FC<TextInputProps> = ({
  label,
  customClassName,
  errorMessage,
  placeholder,
  type = "password",
  ...props
}) => {
  const [showPassword, setShowPassword] = useState(false);
  const isPasswordType = type === "password";

  return (
    <div className={commonStyles.inputWrapper}>
      {label && (
        <label htmlFor={inputId} className={commonStyles.labelInput}>
          {label}
        </label>
      )}

      <div className={commonStyles.inputContainer}>
        <input
          id={inputId}
          name={name}
          type={inputType}
          className={`${commonStyles.textInput} ${customClassName} ${
            errorMessage ? commonStyles.inputError : ""
          } ${isPasswordType ? commonStyles.hasIcon : ""}`}
          placeholder={placeholder}
          value={value}
          onChange={onChange}
          disabled={disabled}
          aria-invalid={!!errorMessage}
          aria-describedby={errorMessage ? `${inputId}-error` : undefined}
        />

        {isPasswordType && (
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className={commonStyles.togglePassword}
            disabled={disabled}
            aria-label={showPassword ? "Hide password" : "Show password"}
            tabIndex={-1}
          >
            {showPassword ? (
              <IconEyeOff size={20} stroke={1.5} />
            ) : (
              <IconEye size={20} stroke={1.5} />
            )}
          </button>
        )}
      </div>

      {errorMessage && (
        <span 
          id={`${inputId}-error`}
          className={commonStyles.errorMessage}
          role="alert"
        >
          {errorMessage}
        </span>
      )}
    </div>
  );
};

export default TextInput;
